// Get the four vertices of the tetrahedron
RT::Vertex_handle v0 = c->vertex(0);
RT::Vertex_handle v1 = c->vertex(1);
RT::Vertex_handle v2 = c->vertex(2);
RT::Vertex_handle v3 = c->vertex(3);

// Extract 3D positions and weights
Point p0 = v0->point().point();
Point p1 = v1->point().point();
Point p2 = v2->point().point();
Point p3 = v3->point().point();

double w0 = v0->point().weight();
double w1 = v1->point().weight();
double w2 = v2->point().weight();
double w3 = v3->point().weight();

// Lift points to 4D: (x,y,z, x²+y²+z²-w)
LiftedPoint lp0 = lifted_point(p0.x(), p0.y(), p0.z(), 
                              p0.x()*p0.x() + p0.y()*p0.y() + p0.z()*p0.z() - w0);
LiftedPoint lp1 = lifted_point(p1.x(), p1.y(), p1.z(), 
                              p1.x()*p1.x() + p1.y()*p1.y() + p1.z()*p1.z() - w1);
LiftedPoint lp2 = lifted_point(p2.x(), p2.y(), p2.z(), 
                              p2.x()*p2.x() + p2.y()*p2.y() + p2.z()*p2.z() - w2);
LiftedPoint lp3 = lifted_point(p3.x(), p3.y(), p3.z(), 
                              p3.x()*p3.x() + p3.y()*p3.y() + p3.z()*p3.z() - w3);

// Create hyperplane from 4 lifted points
HyperPlane plane = HyperPlane(lp0, lp1, lp2, lp3);

// Extract normal vector coefficients
double a = plane.coefficient(0);
double b = plane.coefficient(1);
double c = plane.coefficient(2);
double d = plane.coefficient(3);

// Normalize and extract velocity components
double denom = 2.0 * d;
if (std::abs(denom) < 1e-12) {
    return Vector(0, 0, 0);
}

return Vector(-a/denom, -b/denom, -c/denom);

